1	import type { Item } from "./claim-office.js";
2	import { quote } from "./claim-office.js";
3	
4	// A scenario is the parsed input format: a customer and a list of steps to run
5	// against them. Running a scenario is deliberately separate from the CLI that
6	// wraps it — reading stdin, writing stdout and setting an exit status are I/O
7	// concerns, while sequencing steps is not. Keeping them apart lets the step
8	// logic be exercised without a process.
9	
10	// The scenario names a customer by years alone. Previous contracts are not
11	// given: they are derived from the step's position, since each quote step is
12	// itself a contract.
13	export type ScenarioCustomer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Step = {
18	  op: string;
19	  items?: Item[];
20	};
21	
22	export type Scenario = {
23	  customer: ScenarioCustomer;
24	  steps: Step[];
25	};
26	
27	export type StepResult = {
28	  premium?: number;
29	};
30	
31	// Each quote step signs one contract, so by the time step n runs the customer
32	// already holds n of them. That makes "previous contracts" the step's own index
33	// rather than a running total that has to be kept in step by hand.
34	const previousContractsAt = (stepIndex: number): number => stepIndex;
35	
36	const runStep = (
37	  customer: ScenarioCustomer,
38	  step: Step,
39	  stepIndex: number,
40	): StepResult => ({
41	  premium: quote(
42	    {
43	      yearsWithMHPCO: customer.yearsWithMHPCO,
44	      previousContracts: previousContractsAt(stepIndex),
45	    },
46	    step.items ?? [],
47	  ),
48	});
49	
50	export const runScenario = (scenario: Scenario): StepResult[] =>
51	  scenario.steps.map((step, stepIndex) =>
52	    runStep(scenario.customer, step, stepIndex),
53	  );
