it("should return a premium for a quote step and a payout with remainingCap for a claim step", () => {
  expect(
    runScenario({
      customer: { yearsWithMHPCO: 5 },
      steps: [
        {
          op: "quote",
          items: [
            {
              type: "amulet",
              material: "silver",
              enchantment: 2,
              cursed: false,
            },
          ],
        },
        {
          op: "claim",
          policy: 0,
          incident: {
            cause: "fire",
            damages: [{ itemType: "amulet", amount: 200 }],
          },
        },
      ],
    }),
  ).toEqual([{ premium: 59 }, { payout: 100, remainingCap: 1100 }]);
});

